from __future__ import annotations
from dataclasses import dataclass
from fractions import Fraction
from typing import Sequence, Union

@dataclass(frozen=True)
class Monomial:
    coefficient: Fraction
    degree: int

@dataclass(frozen=True)
class SimplePole:
    residue: Fraction
    pole: Fraction

@dataclass(frozen=True)
class HigherPole:
    coefficient: Fraction
    pole: Fraction
    order: int

@dataclass(frozen=True)
class Exponential:
    coefficient: Fraction
    rate: Fraction

Piece = Union[Monomial, SimplePole, HigherPole, Exponential]

def primitive_text(pieces: Sequence[Piece]) -> list[str]:
    out: list[str] = []
    for p in pieces:
        if isinstance(p, Monomial):
            if p.degree < 0:
                raise ValueError("negative degree")
            out.append(f"({p.coefficient}/{p.degree + 1})*x^{p.degree + 1}")
        elif isinstance(p, SimplePole):
            out.append(f"({p.residue})*log|x-({p.pole})|")
        elif isinstance(p, HigherPole):
            if p.order < 2:
                raise ValueError("higher-pole order must be at least 2")
            out.append(f"({-p.coefficient / (p.order - 1)})/(x-({p.pole}))^{p.order - 1}")
        else:
            if p.rate == 0:
                out.append(f"({p.coefficient})*x")
            else:
                out.append(f"({p.coefficient / p.rate})*exp(({p.rate})*x)")
    return out

